// Builds the typed index the site reads, from every `<name>.meta.ts` in packages/ui/src (ADR 0008),
// and the shadcn registry users install from (apps/www/public/r, ADR 0009).
//
//   node scripts/build-index.mjs           validate the metadata and write the generated files and the registry
//   node scripts/build-index.mjs --check   fail if the generated files are out of date (part of `pnpm check`);
//                                          the registry is still built in memory, so its errors are caught too
//
// Node 22.18+ runs the TypeScript metadata directly (type stripping), so metadata files may only use
// erasable syntax (`import type`, `satisfies`, `as const`) and must import local files with a `.ts` extension.

import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { createRegistry } from "./registry/build-registry.mjs";
import { buildSkillZips } from "./skills/build-skill-zips.mjs";

const ROOT = resolve(fileURLToPath(new URL(".", import.meta.url)), "..");
const SRC = join(ROOT, "packages", "ui", "src");
const OUT_INDEX = join(SRC, "registry", "index.generated.ts");
const OUT_DEMOS = join(SRC, "registry", "demos.generated.tsx");
const CHECK = process.argv.includes("--check");

const { itemSchema } = await import(pathToFileURL(join(SRC, "registry", "schema.ts")).href);
const { kinds } = await import(pathToFileURL(join(SRC, "registry", "kinds.ts")).href);

const toPosix = (p) => p.split(sep).join("/");
const metaFiles = readdirSync(SRC, { recursive: true })
  .map(String)
  .filter((f) => f.endsWith(".meta.ts"))
  .map((f) => join(SRC, f))
  .sort();

const errors = [];
const items = [];

for (const file of metaFiles) {
  const rel = toPosix(relative(SRC, file));
  const dir = toPosix(dirname(rel));
  const mod = await import(pathToFileURL(file).href);
  const parsed = itemSchema.safeParse(mod.default);
  if (!parsed.success) {
    for (const issue of parsed.error.issues) {
      errors.push(`${rel}: ${issue.path.join(".") || "(root)"}: ${issue.message}`);
    }
    continue;
  }
  const item = parsed.data;
  if (basename(dir) !== item.name) errors.push(`${rel}: the folder must be named "${item.name}"`);
  if (basename(file, ".meta.ts") !== item.name)
    errors.push(`${rel}: the file must be named ${item.name}.meta.ts`);
  for (const f of item.files) {
    if (!existsSync(join(SRC, dir, f))) errors.push(`${rel}: missing file ${f}`);
  }
  for (const demo of item.demos) {
    if (!existsSync(join(SRC, dir, "demos", `${demo.name}.tsx`))) {
      errors.push(`${rel}: missing demo demos/${demo.name}.tsx`);
    }
  }
  const card = item.preview.card;
  if (card && !existsSync(join(SRC, dir, "demos", `${card}.tsx`))) {
    errors.push(`${rel}: missing card demo demos/${card}.tsx`);
  }
  items.push({ ...item, href: `/${kinds[item.kind].segment}/${item.name}`, dir });
}

// Names are unique across kinds: they are also registry names (@fewtone/<name>)
const seen = new Map();
for (const item of items) {
  if (seen.has(item.name))
    errors.push(`duplicate name "${item.name}" in ${seen.get(item.name)} and ${item.dir}`);
  seen.set(item.name, item.dir);
}
for (const item of items) {
  for (const ref of [...item.related, ...item.registryDependencies]) {
    if (!seen.has(ref)) errors.push(`${item.dir}: refers to unknown item "${ref}"`);
  }
}

if (errors.length > 0) {
  console.error(`Item metadata has ${errors.length} problem(s):\n${errors.map((e) => `  ${e}`).join("\n")}`);
  process.exit(1);
}

items.sort((a, b) => kinds[a.kind].order - kinds[b.kind].order || a.title.localeCompare(b.title));

// Install data (npm and registry dependencies) is derived from imports, alongside the registry JSON
const registry = await createRegistry({ root: ROOT, items, kinds });
if (registry.errors.length > 0) {
  console.error(
    `The registry has ${registry.errors.length} problem(s):\n${registry.errors.map((e) => `  ${e}`).join("\n")}`,
  );
  process.exit(1);
}
for (const item of items) item.install = registry.install.get(item.name);

const banner =
  "// Generated by scripts/build-index.mjs from the *.meta.ts files. Do not edit: run `pnpm index`.\n";

const indexSource = `${banner}import type { Item } from "./schema.ts";

export const items: Item[] = ${JSON.stringify(items, null, 2)};

/** The tokens item as CSS to paste, for the Manual install route (generated from tokens.css and theme.css) */
export const tokensCss = ${JSON.stringify(registry.manualCss)};
`;

let imports = "";
let entries = "";
let n = 0;
for (const item of items) {
  // The page's demos, plus the card-only demo when there is one
  const names = item.demos.map((demo) => demo.name);
  if (item.preview.card && !names.includes(item.preview.card)) names.push(item.preview.card);
  for (const name of names) {
    const id = `Demo${n++}`;
    imports += `import ${id} from "../${item.dir}/demos/${name}";\n`;
    entries += `  "${item.name}/${name}": ${id},\n`;
  }
}
const demosSource = `${banner}import type { ComponentType } from "react";
${imports}
/** Every demo component, keyed by "<item>/<demo>" */
export const demos: Record<string, ComponentType> = {
${entries}};
`;

// The README's component list, between its markers, so the repo's front page never drifts from the index
const README = join(ROOT, "README.md");
// The published site, never a local REGISTRY_URL: the README links to the real pages
const { registryBase } = await import(pathToFileURL(join(SRC, "registry", "shared.ts")).href);
const siteUrl = new URL(registryBase).origin;

function readmeSource() {
  const current = readFileSync(README, "utf8").replace(/\r\n/g, "\n");
  const markers = /(<!-- components:start[^>]*-->\n)[\s\S]*?(<!-- components:end -->)/;
  if (!markers.test(current)) {
    console.error("README.md is missing its <!-- components:start --> / <!-- components:end --> markers.");
    process.exit(1);
  }
  const shown = items.filter((item) => item.status !== "draft");
  const rows = [];
  for (const [name, kind] of Object.entries(kinds).sort(([, a], [, b]) => a.order - b.order)) {
    const groups = new Map();
    for (const item of shown.filter((entry) => entry.kind === name)) {
      // Components by category; any other kind (backgrounds, blocks…) as one row
      const label = name === "component" ? item.category : kind.plural;
      groups.set(label, [...(groups.get(label) ?? []), item]);
    }
    for (const [label, members] of [...groups].sort(([a], [b]) => a.localeCompare(b))) {
      rows.push(
        `| ${label} | ${members.map((item) => `[${item.title}](${siteUrl}${item.href})`).join(", ")} |`,
      );
    }
  }
  const count = shown.filter((item) => item.kind === "component").length;
  const section = [
    `${count} components, each with a live preview, examples and its API on [ui.fewtone.com](${siteUrl}/components).`,
    "",
    "| Category | Components |",
    "| --- | --- |",
    ...rows,
  ].join("\n");
  return current.replace(markers, (_, start, end) => `${start}${section}\n${end}`);
}

const outputs = [
  [OUT_INDEX, indexSource],
  [OUT_DEMOS, demosSource],
  [README, readmeSource()],
];

if (CHECK) {
  const stale = outputs.filter(([path, source]) => {
    const current = existsSync(path) ? readFileSync(path, "utf8").replace(/\r\n/g, "\n") : "";
    return current !== source;
  });
  if (stale.length > 0) {
    console.error(
      `The item index is out of date: ${stale.map(([p]) => toPosix(relative(ROOT, p))).join(", ")}. Run \`pnpm index\`.`,
    );
    process.exit(1);
  }
  console.log(`Item index is up to date (${items.length} item${items.length === 1 ? "" : "s"}).`);
} else {
  for (const [path, source] of outputs) writeFileSync(path, source);
  const written = registry.write();
  // The public skills' downloads (apps/www/public/skills, ADR 0013)
  const skills = buildSkillZips(ROOT);
  console.log(
    `Wrote the item index (${items.length} item${items.length === 1 ? "" : "s"}), ${written} registry files and ${skills.length} skill zip${skills.length === 1 ? "" : "s"}.`,
  );
}
